/**
 * Every route is registered here up front so workstreams only ever edit their own page files.
 * Replit Agent: do NOT edit this file. Ask for a route change instead.
 */
import { Navigate, createBrowserRouter } from "react-router";
import { AppLayout, DemoLayout, RootLayout } from "./layouts";
import LandingPage from "@/features/landing/LandingPage";
import StyleguidePage from "@/features/system/StyleguidePage";
import { NotFoundPage, RouteErrorPage } from "@/features/system/SystemPages";
import WardrobePage from "@/features/wardrobe/WardrobePage";
import ItemDetailPage from "@/features/wardrobe/ItemDetailPage";
import AddItemsPage from "@/features/wardrobe/AddItemsPage";
import EditItemPage from "@/features/wardrobe/EditItemPage";
import StylePage from "@/features/style/StylePage";
import LookbookPage from "@/features/lookbook/LookbookPage";
import OutfitDetailPage from "@/features/lookbook/OutfitDetailPage";
import ProfilePage from "@/features/profile/ProfilePage";
import SignInPage from "@/features/auth/SignInPage";
import SignUpPage from "@/features/auth/SignUpPage";
import AuthCallbackPage from "@/features/auth/AuthCallbackPage";
import OnboardingPage from "@/features/onboarding/OnboardingPage";

/** Screens shared by the demo and the signed-in app. */
const sharedWardrobeRoutes = [
  { index: true, element: <Navigate to="wardrobe" replace /> },
  { path: "wardrobe", element: <WardrobePage /> },
  // Static segments rank above the item identifier route.
  { path: "wardrobe/new", element: <AddItemsPage /> },
  { path: "wardrobe/:itemId/edit", element: <EditItemPage /> },
  { path: "wardrobe/:itemId", element: <ItemDetailPage /> },
  { path: "style", element: <StylePage /> },
  { path: "lookbook", element: <LookbookPage /> },
  { path: "lookbook/:outfitId", element: <OutfitDetailPage /> },
];

export const router = createBrowserRouter([
  {
    element: <RootLayout />,
    errorElement: <RouteErrorPage />,
    children: [
      { path: "/", element: <LandingPage /> },
      { path: "/styleguide", element: <StyleguidePage /> },
      { path: "/auth/sign-in", element: <SignInPage /> },
      { path: "/auth/sign-up", element: <SignUpPage /> },
      { path: "/auth/callback", element: <AuthCallbackPage /> },
      { path: "/onboarding", element: <OnboardingPage /> },
      {
        path: "/demo",
        element: <DemoLayout />,
        children: sharedWardrobeRoutes,
      },
      {
        path: "/app",
        element: <AppLayout />,
        children: [
          { path: "profile", element: <ProfilePage /> },
          // Milestone 4 approved entry point; reuse Studio's existing Ideas mode.
          { path: "ideas", element: <Navigate to="/app/style?mode=ideas" replace /> },
          ...sharedWardrobeRoutes,
        ],
      },
      { path: "*", element: <NotFoundPage /> },
    ],
  },
]);
